CREATE TABLE IF NOT EXISTS bookings (id INTEGER PRIMARY KEY, room_id INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS log (id INTEGER PRIMARY KEY, booking_id INTEGER);
CREATE TRIGGER IF NOT EXISTS log_bookings AFTER INSERT ON bookings BEGIN INSERT INTO log (booking_id) VALUES (NEW.id); END;

CREATE TABLE IF NOT EXISTS bookings (id INTEGER PRIMARY KEY, cancelled_at INTEGER);
CREATE VIEW IF NOT EXISTS live AS SELECT id FROM bookings WHERE cancelled_at IS NULL;
CREATE TRIGGER IF NOT EXISTS stamp AFTER UPDATE ON bookings BEGIN UPDATE bookings SET cancelled_at = 1 WHERE id = NEW.id; END;
